/* Kestrel Components (Manufacturing) - source database seed for the pipeline Copy demo
   Plays the role of: Manufacturing Execution System (on-prem SQL Server)
   Run this whole script ONCE in a Fabric SQL database (or Azure SQL / SQL Server). Then release the days in order:
       EXEC src.usp_release_day 1;   -- before the first pipeline run
       EXEC src.usp_release_day 2;   -- before the second run
       EXEC src.usp_release_day 3;   -- before the third run (adds a new column = schema drift)
   Generated by tools/build_kit.py - all data is fictional. */
IF SCHEMA_ID('src') IS NULL EXEC('CREATE SCHEMA src');
GO
DROP TABLE IF EXISTS src.machines; DROP TABLE IF EXISTS src.maintenance_orders; DROP TABLE IF EXISTS src.stage_machines; DROP TABLE IF EXISTS src.stage_maintenance_orders;
CREATE TABLE src.machines (machine_id INT NOT NULL, machine_code NVARCHAR(30), machine_name NVARCHAR(100), machine_type NVARCHAR(30), plant NVARCHAR(40), status NVARCHAR(30), criticality INT, rated_units_per_hour DECIMAL(12,1), commissioned_date DATE, last_modified DATETIME2(0), CONSTRAINT pk_machines PRIMARY KEY (machine_id));
CREATE TABLE src.maintenance_orders (mo_id INT NOT NULL, machine_id INT, mo_type NVARCHAR(30), priority INT, status NVARCHAR(30), reported_ts DATETIME2(0), finished_ts DATETIME2(0), parts_cost_aud DECIMAL(12,2), downtime_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0), CONSTRAINT pk_maintenance_orders PRIMARY KEY (mo_id));
CREATE TABLE src.stage_machines (release_day INT NOT NULL, machine_id INT, machine_code NVARCHAR(30), machine_name NVARCHAR(100), machine_type NVARCHAR(30), plant NVARCHAR(40), status NVARCHAR(30), criticality INT, rated_units_per_hour DECIMAL(12,1), commissioned_date DATE, last_modified DATETIME2(0), line_supervisor NVARCHAR(50));
CREATE TABLE src.stage_maintenance_orders (release_day INT NOT NULL, mo_id INT, machine_id INT, mo_type NVARCHAR(30), priority INT, status NVARCHAR(30), reported_ts DATETIME2(0), finished_ts DATETIME2(0), parts_cost_aud DECIMAL(12,2), downtime_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0));
GO
GO
CREATE OR ALTER PROCEDURE src.usp_release_day @day INT
AS
BEGIN
    SET NOCOUNT ON;
    IF @day >= 3 AND COL_LENGTH('src.machines', 'line_supervisor') IS NULL
        EXEC('ALTER TABLE src.machines ADD line_supervisor NVARCHAR(50) NULL');
    DELETE t FROM src.machines t WHERE EXISTS (SELECT 1 FROM src.stage_machines s WHERE s.release_day = @day AND s.machine_id = t.machine_id);
    IF @day >= 3
        EXEC('UPDATE t SET t.line_supervisor = s.line_supervisor FROM src.machines t JOIN src.stage_machines s ON s.machine_id = t.machine_id AND s.release_day = 3');
    DELETE t FROM src.maintenance_orders t WHERE EXISTS (SELECT 1 FROM src.stage_maintenance_orders s WHERE s.release_day = @day AND s.mo_id = t.mo_id);
    SELECT @day AS released_day, (SELECT COUNT(*) FROM src.machines) AS machines, (SELECT COUNT(*) FROM src.maintenance_orders) AS maintenance_orders;
END;
GO
