    INSERT INTO src.machines (machine_id, machine_code, machine_name, machine_type, plant, status, criticality, rated_units_per_hour, commissioned_date, last_modified) SELECT machine_id, machine_code, machine_name, machine_type, plant, status, criticality, rated_units_per_hour, commissioned_date, last_modified FROM src.stage_machines WHERE release_day = @day;
    INSERT INTO src.maintenance_orders (mo_id, machine_id, mo_type, priority, status, reported_ts, finished_ts, parts_cost_aud, downtime_hours, description, last_modified) SELECT mo_id, machine_id, mo_type, priority, status, reported_ts, finished_ts, parts_cost_aud, downtime_hours, description, last_modified FROM src.stage_maintenance_orders WHERE release_day = @day;
